                wait until falling_edge(clk);
                if i>0 then
                    held:=to_integer(dout);
                    held_valid:=valid;
                end if;
                rst<=sl(resets(i)=1);
                ce<=sl(enables(i)=1);
                din<=to_signed(inputs(i),din'length);
                wait for 1 ns;
                if i>0 then
                    assert to_integer(dout)=held and valid=held_valid
                    report "synchronous outputs changed before clock edge" severity failure;
                end if;
                wait until rising_edge(clk);
                wait for 1 ns;
                assert to_integer(dout)=outputs(i)
                report "accepted sample model, reset priority, numerical precision or output hold" severity failure;
                assert valid=sl(valids(i)=1)
                report "startup validity or disabled-cycle valid pulse" severity failure;
            end loop;
            finished(1) <= true;
            wait;
        end process;
    end block;
